interactions.query:
query BoardItems($owner: String!, $number: Int!, $status: String!, $cursor: String, $count0: String!, $count1: String!, $count2: String!, $count3: String!, $filter: String!) {
  viewer { login }
  repositoryOwner(login: $owner) {
    ... on User { projectV2(number: $number) { ...items } }
    ... on Organization { projectV2(number: $number) { ...items } }
  }
}

fragment items on ProjectV2 {
  field(name: $status) { ... on ProjectV2SingleSelectField { id } }
  count0: items(first: 0, query: $count0) { totalCount }
  count1: items(first: 0, query: $count1) { totalCount }
  count2: items(first: 0, query: $count2) { totalCount }
  count3: items(first: 0, query: $count3) { totalCount }
  items(first: 100, after: $cursor, query: $filter) {
    totalCount
    pageInfo { hasNextPage endCursor }
    nodes {
      status: fieldValueByName(name: $status) {
        ... on ProjectV2ItemFieldSingleSelectValue { name }
      }
      content {
        __typename
        ... on Issue {
          number
          title
          state
          repository { nameWithOwner }
          labels(first: 100) { totalCount nodes { name } }
          assignees(first: 10) { totalCount nodes { login } }
        }
      }
    }
  }
}
